// scripts/emit-code-fields.js - Re-emit rolink-extension/core/code-fields.js
// from generated/code-fields.json. Run after `npm run generate:code-fields`.

import { readFile, writeFile } from "node:fs/promises";

const src = JSON.parse(await readFile("generated/code-fields.json", "utf8"));
const out = `// rolink-extension/core/code-fields.js — GENERATED. Do not edit by hand.
// Re-emit with: node scripts/emit-code-fields.js
//
// Source of truth: generated/code-fields.json (regenerated by
// \`npm run generate:code-fields\`).
//
// Loaded by the content scripts (see rolink-extension/manifest.json) BEFORE
// core/parser.js so parser.js can dynamically accept ###RAW:<field>### for any
// string field declared in any tool's Zod inputSchema.
window.ROLINK_CODE_FIELDS = ${JSON.stringify(src, null, 2)};
`;
await writeFile("rolink-extension/core/code-fields.js", out, "utf8");
console.log(`emitted rolink-extension/core/code-fields.js (${src.toolCount} tools, ${src.stringFields.length} string fields)`);
